from pathlib import Path

p = Path('lib/tz_build.dart')
s = p.read_text(encoding='utf-8')

# The previous registration patch referenced SetPasswordPage even when that helper was not emitted.
s = s.replace("    if (role == 'agent' && passwordSet == false) return const SetPasswordPage();\n", "")

# Replace the generated AgentsPage with a deliberately simple, parser-safe implementation.
start = s.find('class AgentsPage extends')
reg = s.find('class AgentRegistrationPage extends')
if start >= 0 and reg > start:
    agents = '''class AgentsPage extends StatefulWidget {\n  const AgentsPage({super.key});\n  @override\n  State<AgentsPage> createState() => _AgentsPageState();\n}\n\nclass _AgentsPageState extends State<AgentsPage> {\n  late Future<List<Map<String, dynamic>>> future;\n\n  @override\n  void initState() {\n    super.initState();\n    future = loadAgents();\n  }\n\n  Future<List<Map<String, dynamic>>> loadAgents() async {\n    final rows = await db.from('profiles').select('id,full_name,email,phone,state,available,agent_approval_status').eq('role', 'agent').order('full_name');\n    return List<Map<String, dynamic>>.from(rows);\n  }\n\n  Future<void> approval(String id, String status) async {\n    try {\n      await db.rpc('tz_set_agent_approval', params: {'p_agent': id, 'p_status': status});\n      if (mounted) setState(() => future = loadAgents());\n    } catch (e) {\n      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));\n    }\n  }\n\n  Future<void> active(String id, bool value) async {\n    try {\n      await db.rpc('tz_set_agent_active', params: {'p_agent': id, 'p_active': value});\n      if (mounted) setState(() => future = loadAgents());\n    } catch (e) {\n      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return FutureBuilder<List<Map<String, dynamic>>>(\n      future: future,\n      builder: (context, snap) {\n        if (!snap.hasData) return const Center(child: CircularProgressIndicator());\n        final rows = snap.data!;\n        return ListView(\n          padding: const EdgeInsets.all(14),\n          children: [\n            const Text('Agents', style: TextStyle(fontSize: 26, fontWeight: FontWeight.w900, color: navy)),\n            const SizedBox(height: 8),\n            const Text('Approve new agent registrations here.'),\n            const SizedBox(height: 12),\n            for (final a in rows)\n              Card(\n                child: Padding(\n                  padding: const EdgeInsets.all(12),\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text('${a['full_name'] ?? 'Unnamed agent'}', style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 17)),\n                      const SizedBox(height: 4),\n                      Text('${a['email'] ?? ''}'),\n                      Text('${a['phone'] ?? ''} • ${a['state'] ?? ''}'),\n                      const SizedBox(height: 6),\n                      Text('Status: ${a['agent_approval_status'] ?? 'approved'}'),\n                      const SizedBox(height: 8),\n                      if (a['agent_approval_status'] == 'pending')\n                        Row(children: [\n                          Expanded(child: FilledButton(onPressed: () => approval('${a['id']}', 'approved'), child: const Text('APPROVE'))),\n                          const SizedBox(width: 8),\n                          Expanded(child: OutlinedButton(onPressed: () => approval('${a['id']}', 'rejected'), child: const Text('REJECT'))),\n                        ]),\n                      if (a['agent_approval_status'] == 'approved')\n                        SizedBox(width: double.infinity, child: OutlinedButton(onPressed: () => active('${a['id']}', !(a['available'] == true)), child: Text(a['available'] == true ? 'REMOVE AGENT' : 'RESTORE AGENT'))),\n                    ],\n                  ),\n                ),\n              ),\n          ],\n        );\n      },\n    );\n  }\n}\n\n'''
    s = s[:start] + agents + s[reg:]

# Replace the registration page with a compact implementation to eliminate dense syntax.
start = s.find('class AgentRegistrationPage extends')
stock = s.find('class StockPage extends')
if start >= 0 and stock > start:
    registration = '''class AgentRegistrationPage extends StatefulWidget {\n  const AgentRegistrationPage({super.key});\n  @override\n  State<AgentRegistrationPage> createState() => _AgentRegistrationPageState();\n}\n\nclass _AgentRegistrationPageState extends State<AgentRegistrationPage> {\n  final name = TextEditingController();\n  final email = TextEditingController();\n  final phone = TextEditingController();\n  final state = TextEditingController();\n  final password = TextEditingController();\n  final confirm = TextEditingController();\n  bool busy = false;\n\n  Future<void> register() async {\n    final n = name.text.trim();\n    final e = email.text.trim().toLowerCase();\n    if (n.isEmpty || !e.contains('@') || phone.text.trim().isEmpty || state.text.trim().isEmpty || password.text.length < 8 || password.text != confirm.text) {\n      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Complete all fields. Passwords must match and contain at least 8 characters.')));\n      return;\n    }\n    setState(() => busy = true);\n    try {\n      await db.auth.signUp(email: e, password: password.text, data: {\n        'full_name': n,\n        'phone': phone.text.trim(),\n        'state': state.text.trim(),\n        'registration_type': 'agent',\n      });\n      await db.auth.signOut();\n      if (!mounted) return;\n      await showDialog<void>(\n        context: context,\n        builder: (_) => AlertDialog(\n          title: const Text('Registration submitted'),\n          content: const Text('Your registration has been submitted. A Temz Store administrator must approve it before you can sign in.'),\n          actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('OK'))],\n        ),\n      );\n      if (mounted) Navigator.pop(context);\n    } on AuthException catch (e) {\n      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message)));\n    } catch (e) {\n      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Registration failed: $e')));\n    } finally {\n      if (mounted) setState(() => busy = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Register as Agent')),\n      body: ListView(\n        padding: const EdgeInsets.all(22),\n        children: [\n          const Logo(size: 105),\n          const SizedBox(height: 12),\n          const Text('Join Temz Store as an Agent', style: TextStyle(fontSize: 25, fontWeight: FontWeight.w900, color: navy)),\n          const SizedBox(height: 8),\n          const Text('Submit your details. An administrator will review and approve your registration.'),\n          const SizedBox(height: 20),\n          TextField(controller: name, decoration: const InputDecoration(labelText: 'Full name')),\n          const SizedBox(height: 12),\n          TextField(controller: email, keyboardType: TextInputType.emailAddress, decoration: const InputDecoration(labelText: 'Email')),\n          const SizedBox(height: 12),\n          TextField(controller: phone, keyboardType: TextInputType.phone, decoration: const InputDecoration(labelText: 'Phone number')),\n          const SizedBox(height: 12),\n          TextField(controller: state, decoration: const InputDecoration(labelText: 'State')),\n          const SizedBox(height: 12),\n          TextField(controller: password, obscureText: true, decoration: const InputDecoration(labelText: 'Create password (8+ characters)')),\n          const SizedBox(height: 12),\n          TextField(controller: confirm, obscureText: true, decoration: const InputDecoration(labelText: 'Confirm password')),\n          const SizedBox(height: 20),\n          SizedBox(height: 52, child: FilledButton(onPressed: busy ? null : register, child: busy ? const CircularProgressIndicator(color: Colors.white) : const Text('SUBMIT REGISTRATION'))),\n        ],\n      ),\n    );\n  }\n}\n\n'''
    s = s[:start] + registration + s[stock:]

p.write_text(s, encoding='utf-8')
print('Applied parser-safe agent registration and approval workflow.')
